def is_plain_name(name: str) -> bool:
    """True when name is one path component: no separators, no dot segments, not empty."""
    pre name.char_count() > 0
    ex is_plain_name("a.txt") == True
    ex is_plain_name("../x") == False
    ex is_plain_name("a/b") == False
    if name == "." or name == "..":
        return False
    for ch in name.chars():
        if ch == "/" or ch == "\\":
            return False
    return True

def first_readable(names: list[str]) -> str uses fs:
    """Text of the first name in names readable inside notes/, or "" when none is.

    Confines fs to notes/ with `with fs = fs.sub("notes"):`. Names that are not
    plain components are skipped. A missing or unreadable file yields no result
    and the search continues. No name may reach a file outside notes/.
    """
    pre names.len() >= 0
    with fs = fs.sub("notes"):
        for name in names:
            if not is_plain_name(name):
                continue
            text = read_note(name)
            if text is not None:
                return text
    return ""

def read_note(name: str) -> str | None uses fs:
    """Text of the file name inside the current fs scope, or None when it cannot be read."""
    return fs.read_text(name) else None
